// Ported from the Node app's Sequelize model UserGroupMember (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class UserGroupMemberConfiguration : IEntityTypeConfiguration<UserGroupMember>
{
    public void Configure(EntityTypeBuilder<UserGroupMember> builder)
    {
        builder.ToTable("user_group_members");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.GroupId).HasColumnName("group_id");
        builder.Property(e => e.UserId).HasColumnName("user_id");
        builder.HasIndex(e => new { e.GroupId, e.UserId }).IsUnique().HasDatabaseName("uq_group_member");
        builder.HasOne(e => e.UserGroup).WithMany(p => p.UserGroupMembers).HasForeignKey(e => e.GroupId).OnDelete(DeleteBehavior.NoAction);
        builder.HasOne(e => e.User).WithMany(p => p.UserGroupMembers).HasForeignKey(e => e.UserId).OnDelete(DeleteBehavior.NoAction);
    }
}
